  // ===== Integrations =====
  "itg.intro": { fr: "Services externes branchés sur le site du client. Réservé à MOODD : le code collé ici s'exécute sur le site public.", en: "External services connected to the client's site. MOODD only: code pasted here runs on the public site.", it: "Servizi esterni collegati al sito del cliente. Riservato a MOODD: il codice incollato qui viene eseguito sul sito pubblico.", nl: "Externe diensten gekoppeld aan de site van de klant. Alleen MOODD: hier geplakte code draait op de publieke site.", es: "Servicios externos conectados al sitio del cliente. Solo MOODD: el código pegado aquí se ejecuta en el sitio público." },
  "itg.resa.who": { fr: "Qui gère les réservations sur le site du client.", en: "Who manages reservations on the client's site.", it: "Chi gestisce le prenotazioni sul sito del cliente.", nl: "Wie de reserveringen op de site van de klant beheert.", es: "Quién gestiona las reservas en el sitio del cliente." },
