  "itg.mode.moodd.desc": { fr: "Le widget MOODD gère les réservations : agenda, plan de salle, emails, statistiques.", en: "The MOODD widget manages reservations: calendar, floor plan, emails, statistics.", it: "Il widget MOODD gestisce le prenotazioni: agenda, piantina, email, statistiche.", nl: "De MOODD-widget beheert reserveringen: agenda, plattegrond, e-mails, statistieken.", es: "El widget MOODD gestiona las reservas: agenda, plano de sala, correos, estadísticas." },
  "itg.mode.link.desc": { fr: "Le bouton « Réserver » du site renvoie vers la page du fournisseur.", en: "The site's « Book » button links to the provider's page.", it: "Il pulsante « Prenota » del sito rimanda alla pagina del fornitore.", nl: "De « Reserveren »-knop van de site verwijst naar de pagina van de aanbieder.", es: "El botón « Reservar » del sitio enlaza a la página del proveedor." },
  "itg.mode.embed.desc": { fr: "Le widget du fournisseur est intégré dans le site du client.", en: "The provider's widget is embedded in the client's site.", it: "Il widget del fornitore è integrato nel sito del cliente.", nl: "De widget van de aanbieder is in de site van de klant ingebed.", es: "El widget del proveedor está integrado en el sitio del cliente." },
  "itg.mode.none.desc": { fr: "Aucune réservation en ligne (take-away uniquement).", en: "No online reservations (take-away only).", it: "Nessuna prenotazione online (solo asporto).", nl: "Geen online reserveringen (alleen afhalen).", es: "Sin reservas en línea (solo para llevar)." },
