  "set.res.minNotice": { fr: "Délai minimum avant réservation (min)", en: "Minimum notice before booking (min)", it: "Preavviso minimo prima della prenotazione (min)", nl: "Minimale voorafgaande tijd voor reserveren (min)", es: "Antelación mínima antes de reservar (min)" },
  "set.res.minNoticeHint": { fr: "Ex. 240 : à 18:00, le premier créneau proposé est 22:00. 0 = réservable jusqu'à la dernière minute.", en: "E.g. 240: at 18:00, the first slot offered is 22:00. 0 = bookable until the last minute.", it: "Es. 240: alle 18:00, la prima fascia proposta è le 22:00. 0 = prenotabile fino all'ultimo minuto.", nl: "Bijv. 240: om 18:00 is het eerste aangeboden tijdvak 22:00. 0 = reserveerbaar tot op de laatste minuut.", es: "Ej. 240: a las 18:00, la primera franja ofrecida es 22:00. 0 = reservable hasta el último minuto." },
